func TestSetBucketSoftDelete_RequestConstruction(t *testing.T) {
	tests := []struct {
		name              string
		enabled           bool
		retentionDays     int
		wantEnabled       bool
		wantRetentionDays int // 0 means the field should be omitted
	}{
		{"enable default", true, 0, true, 0},
		{"enable custom", true, 30, true, 30},
		{"disable", false, 30, false, 0},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var req *http.Request
			var body []byte
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				req = r
				body, _ = io.ReadAll(r.Body)
				w.WriteHeader(http.StatusOK)
			}))
			defer server.Close()

			cli, err := New(context.Background(),
				WithEndpoint(server.URL),
				WithAccessKeypair("test-key", "test-secret"),
			)
			if err != nil {
				t.Fatal(err)
			}

			if _, err := cli.SetBucketSoftDelete(context.Background(), &SetBucketSoftDeleteInput{
				Bucket:        "my-bucket",
				Enabled:       tt.enabled,
				RetentionDays: tt.retentionDays,
			}); err != nil {
				t.Fatal(err)
			}

			if req.Method != http.MethodPatch {
				t.Errorf("method = %q, want PATCH", req.Method)
			}
			if req.URL.Path != "/my-bucket" {
				t.Errorf("path = %q, want /my-bucket", req.URL.Path)
			}
			if got := req.Header.Get("Content-Type"); got != "application/json" {
				t.Errorf("content-type = %q, want application/json", got)
			}

			var parsed patchBucketBody
			if err := json.Unmarshal(body, &parsed); err != nil {
				t.Fatalf("failed to unmarshal body %q: %v", body, err)
			}
			if parsed.SoftDelete.Enabled != tt.wantEnabled {
				t.Errorf("enabled = %v, want %v", parsed.SoftDelete.Enabled, tt.wantEnabled)
			}
			if parsed.SoftDelete.RetentionDays != tt.wantRetentionDays {
				t.Errorf("retention_days = %d, want %d", parsed.SoftDelete.RetentionDays, tt.wantRetentionDays)
			}

			// Confirm retention_days is physically absent from the JSON when omitted.
			hasRetention := jsonHasKey(t, body, "retention_days")
			if tt.wantRetentionDays == 0 && hasRetention {
				t.Error("retention_days should be omitted from JSON when 0")
			}
			if tt.wantRetentionDays != 0 && !hasRetention {
				t.Error("retention_days should be present in JSON when set")
			}
		})
	}
}

// A negative window is not the same as an unset one. Zero means "server
// default"; anything else, negative included, goes to the server so an
// out-of-range window is reported instead of silently becoming 7 days.
func TestSoftDelete_NegativeRetentionDaysReachesServer(t *testing.T) {
	t.Run("SetBucketSoftDelete", func(t *testing.T) {
		var body []byte
		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			body, _ = io.ReadAll(r.Body)
			w.WriteHeader(http.StatusOK)
		}))
		defer server.Close()

		cli, err := New(context.Background(),
			WithEndpoint(server.URL),
			WithAccessKeypair("test-key", "test-secret"),
		)
		if err != nil {
			t.Fatal(err)
		}

		if _, err := cli.SetBucketSoftDelete(context.Background(), &SetBucketSoftDeleteInput{
			Bucket:        "my-bucket",
			Enabled:       true,
			RetentionDays: -1,
		}); err != nil {
			t.Fatal(err)
		}

		var parsed patchBucketBody
		if err := json.Unmarshal(body, &parsed); err != nil {
			t.Fatalf("unmarshalling body %s: %v", body, err)
		}
		if parsed.SoftDelete.RetentionDays != -1 {
			t.Errorf("retention_days = %d, want -1 forwarded to the server", parsed.SoftDelete.RetentionDays)
		}
	})

	t.Run("CreateBucketWithSoftDelete", func(t *testing.T) {
		var req *http.Request
		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			req = r
			w.WriteHeader(http.StatusOK)
		}))
		defer server.Close()

		cli, err := New(context.Background(),
			WithEndpoint(server.URL),
			WithAccessKeypair("test-key", "test-secret"),
			WithPathStyle(true),
		)
		if err != nil {
			t.Fatal(err)
		}

		if _, err := cli.CreateBucketWithSoftDelete(context.Background(), &CreateBucketWithSoftDeleteInput{
			CreateBucketInput: &s3.CreateBucketInput{Bucket: aws.String("my-bucket")},
			RetentionDays:     -1,
		}); err != nil {
			t.Fatal(err)
		}

		if got := req.Header.Get("X-Tigris-Soft-Delete"); got != "-1" {
			t.Errorf("X-Tigris-Soft-Delete = %q, want -1 forwarded to the server", got)
		}
	})
}

