func TestForceDeleteBucket_RequestConstruction(t *testing.T) {
	var req *http.Request
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		req = r
		w.WriteHeader(http.StatusNoContent)
	}))
	defer server.Close()

	cli, err := New(context.Background(),
		WithEndpoint(server.URL),
		WithAccessKeypair("test-key", "test-secret"),
		WithPathStyle(true),
	)
	if err != nil {
		t.Fatal(err)
	}

	if _, err := cli.ForceDeleteBucket(context.Background(), &s3.DeleteBucketInput{
		Bucket: aws.String("my-bucket"),
	}); err != nil {
		t.Fatal(err)
	}

	if req.Method != http.MethodDelete {
		t.Errorf("method = %q, want DELETE", req.Method)
	}
	if got := req.Header.Get("X-Tigris-Force-Delete"); got != "true" {
		t.Errorf("X-Tigris-Force-Delete = %q, want true", got)
	}
}

func TestPermanentlyDeleteObject_RequestConstruction(t *testing.T) {
	var req *http.Request
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		req = r
		w.WriteHeader(http.StatusNoContent)
	}))
	defer server.Close()

	cli, err := New(context.Background(),
		WithEndpoint(server.URL),
		WithAccessKeypair("test-key", "test-secret"),
		WithPathStyle(true),
	)
	if err != nil {
		t.Fatal(err)
	}

	if _, err := cli.PermanentlyDeleteObject(context.Background(), "my-bucket", "my-key", "1775929768707198086"); err != nil {
		t.Fatal(err)
	}

	if req.Method != http.MethodDelete {
		t.Errorf("method = %q, want DELETE", req.Method)
	}
	if req.URL.Path != "/my-bucket/my-key" {
		t.Errorf("path = %q, want /my-bucket/my-key", req.URL.Path)
	}
	if got := req.URL.Query().Get("versionId"); got != "1775929768707198086" {
		t.Errorf("versionId = %q, want 1775929768707198086", got)
	}
	if got := req.Header.Get("X-Tigris-Soft-Delete"); got != "true" {
		t.Errorf("X-Tigris-Soft-Delete = %q, want true", got)
	}
}

func TestCreateBucketWithSoftDelete_RequestConstruction(t *testing.T) {
	tests := []struct {
		name          string
		retentionDays int
		wantHeader    string
	}{
		{"default window", 0, "true"},
		{"custom window", 30, "30"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var req *http.Request
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				req = r
				w.WriteHeader(http.StatusOK)
			}))
			defer server.Close()

			cli, err := New(context.Background(),
				WithEndpoint(server.URL),
				WithAccessKeypair("test-key", "test-secret"),
				WithPathStyle(true),
			)
			if err != nil {
				t.Fatal(err)
			}

			if _, err := cli.CreateBucketWithSoftDelete(context.Background(), &CreateBucketWithSoftDeleteInput{
				CreateBucketInput: &s3.CreateBucketInput{
					Bucket: aws.String("my-bucket"),
				},
				RetentionDays: tt.retentionDays,
			}); err != nil {
				t.Fatal(err)
			}

			if req.Method != http.MethodPut {
				t.Errorf("method = %q, want PUT", req.Method)
			}
			if got := req.Header.Get("X-Tigris-Soft-Delete"); got != tt.wantHeader {
				t.Errorf("X-Tigris-Soft-Delete = %q, want %q", got, tt.wantHeader)
			}
		})
	}
}

func TestRestoreBucket_HTTPError(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusNotFound)
		_, _ = w.Write([]byte(`<Error><Code>NoSuchBucket</Code></Error>`))
	}))
	defer server.Close()

	cli, err := New(context.Background(),
		WithEndpoint(server.URL),
		WithAccessKeypair("test-key", "test-secret"),
	)
	if err != nil {
		t.Fatal(err)
	}

	_, err = cli.RestoreBucket(context.Background(), &RestoreBucketInput{Bucket: "my-bucket"})
	if err == nil {
		t.Fatal("expected error for HTTP 404")
	}

	var apiErr *APIError
	if !errors.As(err, &apiErr) {
		t.Fatalf("error = %v, want *APIError", err)
	}
	if apiErr.Op != "RestoreBucket" {
		t.Errorf("Op = %q, want %q", apiErr.Op, "RestoreBucket")
	}
	if apiErr.StatusCode != http.StatusNotFound {
		t.Errorf("StatusCode = %d, want %d", apiErr.StatusCode, http.StatusNotFound)
	}
	if apiErr.Code != "NoSuchBucket" {
		t.Errorf("Code = %q, want %q", apiErr.Code, "NoSuchBucket")
	}
}

func jsonHasKey(t *testing.T, body []byte, key string) bool {
	t.Helper()
	var generic map[string]json.RawMessage
	if err := json.Unmarshal(body, &generic); err != nil {
		t.Fatalf("failed to unmarshal body: %v", err)
	}
	sd, ok := generic["soft_delete"]
	if !ok {
		t.Fatal("body missing soft_delete object")
	}
	var inner map[string]json.RawMessage
	if err := json.Unmarshal(sd, &inner); err != nil {
		t.Fatalf("failed to unmarshal soft_delete: %v", err)
	}
	_, present := inner[key]
	return present
}

// skipIfNoCreds skips integration tests when Tigris credentials are absent.
func skipIfNoCreds(t *testing.T) {
	t.Helper()
	if os.Getenv("TIGRIS_STORAGE_ACCESS_KEY_ID") == "" ||
		os.Getenv("TIGRIS_STORAGE_SECRET_ACCESS_KEY") == "" {
		t.Skip("skipping: TIGRIS_STORAGE_ACCESS_KEY_ID and TIGRIS_STORAGE_SECRET_ACCESS_KEY not set")
	}
}

// TestSoftDeleteLifecycle_integration exercises the full soft-delete lifecycle
// against a live Tigris endpoint when credentials are available.
func TestSoftDeleteLifecycle_integration(t *testing.T) {
	skipIfNoCreds(t)

	ctx := context.Background()
	cli, err := New(ctx)
	if err != nil {
		t.Fatal(err)
	}

	bucket := "storage-go-softdelete-test-" + strconv.FormatInt(time.Now().UnixNano(), 36)

	if _, err := cli.CreateBucketWithSoftDelete(ctx, &CreateBucketWithSoftDeleteInput{
		CreateBucketInput: &s3.CreateBucketInput{
			Bucket: aws.String(bucket),
		},
		RetentionDays: 7,
	}); err != nil {
		t.Fatalf("CreateBucketWithSoftDelete: %v", err)
	}
	t.Cleanup(func() {
		_, _ = cli.ForceDeleteBucket(ctx, &s3.DeleteBucketInput{Bucket: aws.String(bucket)})
	})

	key := "hello.txt"
	if _, err := cli.PutObject(ctx, &s3.PutObjectInput{
		Bucket: aws.String(bucket),
		Key:    aws.String(key),
		Body:   strings.NewReader("hello world"),
	}); err != nil {
		t.Fatalf("PutObject: %v", err)
	}

	if _, err := cli.DeleteObject(ctx, &s3.DeleteObjectInput{
		Bucket: aws.String(bucket),
		Key:    aws.String(key),
	}); err != nil {
		t.Fatalf("DeleteObject: %v", err)
	}

	listed, err := cli.ListSoftDeletedObjects(ctx, &ListSoftDeletedObjectsInput{Bucket: bucket})
	if err != nil {
		t.Fatalf("ListSoftDeletedObjects: %v", err)
	}
	var found bool
	for _, o := range listed.Objects {
		if o.Key == key && o.SoftDeleted {
			found = true
		}
	}
	if !found {
		t.Errorf("soft-deleted object %q not found in listing: %+v", key, listed.Objects)
	}

	if _, err := cli.RestoreSoftDeletedObject(ctx, &RestoreSoftDeletedObjectInput{
		Bucket: bucket,
		Key:    key,
	}); err != nil {
		t.Fatalf("RestoreSoftDeletedObject: %v", err)
	}

	if _, err := cli.ForceDeleteBucket(ctx, &s3.DeleteBucketInput{Bucket: aws.String(bucket)}); err != nil {
		t.Fatalf("ForceDeleteBucket: %v", err)
	}

	// Soft-delete state is eventually consistent, so poll the deleted-buckets
	// listing (paginating, as other soft-deleted buckets may be present) until
	// the bucket shows up or the deadline passes.
	deadline := time.Now().Add(15 * time.Second)
	for {
		if findSoftDeletedBucket(ctx, t, cli, bucket) {
			break
		}
		if time.Now().After(deadline) {
			t.Fatalf("soft-deleted bucket %q not found in ListSoftDeletedBuckets", bucket)
		}
		time.Sleep(time.Second)
	}
}

// findSoftDeletedBucket reports whether the named bucket appears in the
// soft-deleted buckets listing, following pagination.
func findSoftDeletedBucket(ctx context.Context, t *testing.T, cli *Client, bucket string) bool {
	t.Helper()

	var token string
	for {
		listed, err := cli.ListSoftDeletedBuckets(ctx, &ListSoftDeletedBucketsInput{ContinuationToken: token})
		if err != nil {
			t.Fatalf("ListSoftDeletedBuckets: %v", err)
		}
		for _, b := range listed.Buckets {
			if b.Name == bucket {
				return true
			}
		}
		if !listed.IsTruncated {
			return false
		}
		token = listed.NextContinuationToken
	}
}

// TestSigV4CanonicalPath_NotDoubleEscaped pins the signing rule that Tigris
// applies: the canonical URI is the request path encoded exactly once.
//
// The request path is already percent-encoded when it reaches the signer, so the
// signer must run with DisableURIPathEscaping. Without it the canonical URI is
// encoded a second time and every key holding a space, "%", "+", "#", "?", or a
// non-ASCII byte fails with SignatureDoesNotMatch. Plain ASCII keys are
// unaffected, which is why this needs its own test.
//
// The check re-signs the received request both ways and asserts the client
// matched the single-encoded form. Verifying the reconstruction reproduces the
// client's own Authorization header is what makes the comparison meaningful.
func TestSigV4CanonicalPath_NotDoubleEscaped(t *testing.T) {
	keys := []string{
		"my-key",
		"folder/my file.txt",
		"100%done.txt",
		"café.txt",
		"a+b=c",
		"weird?#&.txt",
	}

	for _, key := range keys {
		t.Run(key, func(t *testing.T) {
			var gotAuth, wantSingle, wantDouble string

			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				gotAuth = r.Header.Get("Authorization")

				signingTime, err := time.Parse("20060102T150405Z", r.Header.Get("X-Amz-Date"))
				if err != nil {
					t.Errorf("parsing X-Amz-Date: %v", err)
					return
				}

				resign := func(disableEscaping bool) string {
					rebuilt, err := http.NewRequest(r.Method, "http://"+r.Host+r.RequestURI, nil)
					if err != nil {
						t.Errorf("rebuilding request: %v", err)
						return ""
					}
					for _, name := range signedHeaderNames(gotAuth) {
						if name == "host" {
							continue
						}
						rebuilt.Header.Set(name, r.Header.Get(name))
					}

					signer := v4.NewSigner(func(o *v4.SignerOptions) {
						o.DisableURIPathEscaping = disableEscaping
					})
					err = signer.SignHTTP(context.Background(),
						aws.Credentials{AccessKeyID: "test-key", SecretAccessKey: "test-secret"},
						rebuilt, r.Header.Get("X-Amz-Content-Sha256"), "s3", "auto", signingTime)
					if err != nil {
						t.Errorf("re-signing: %v", err)
						return ""
					}
					return rebuilt.Header.Get("Authorization")
				}

				wantSingle = resign(true)
				wantDouble = resign(false)
				w.WriteHeader(http.StatusOK)
			}))
			defer server.Close()

			cli, err := New(context.Background(),
				WithEndpoint(server.URL),
				WithAccessKeypair("test-key", "test-secret"),
				WithRegion("auto"),
			)
			if err != nil {
				t.Fatal(err)
			}

			if _, err := cli.RestoreSoftDeletedObject(context.Background(), &RestoreSoftDeletedObjectInput{
				Bucket: "my-bucket",
				Key:    key,
			}); err != nil {
				t.Fatal(err)
			}

			if gotAuth != wantSingle {
				t.Errorf("signature was not computed over the single-encoded path\n got: %s\nwant: %s", gotAuth, wantSingle)
			}
			// Guards the test itself: for a key that the double-escaping bug would
			// corrupt, the two forms must differ, or this test proves nothing.
			if key != "my-key" && wantSingle == wantDouble {
				t.Errorf("key %q does not distinguish single from double escaping; pick another", key)
			}
		})
	}
}

// signedHeaderNames pulls the SignedHeaders list out of a SigV4 Authorization
// header value.
func signedHeaderNames(auth string) []string {
	const marker = "SignedHeaders="
	i := strings.Index(auth, marker)
	if i < 0 {
		return nil
	}
	rest := auth[i+len(marker):]
	if j := strings.Index(rest, ","); j >= 0 {
		rest = rest[:j]
	}
	return strings.Split(rest, ";")
}

// countingHTTPClient records how many requests it sends, so a test can prove the
// raw-HTTP path used it instead of the package-level client.
type countingHTTPClient struct {
	inner *http.Client
	calls int
}

func (c *countingHTTPClient) Do(req *http.Request) (*http.Response, error) {
	c.calls++
	return c.inner.Do(req)
}

// The raw-HTTP methods must send through the HTTPClient configured on the
// underlying S3 client. Discarding it would drop any custom transport, TLS
// config, proxy, or tracing hook the caller installed.
func TestDoSignedRequest_UsesConfiguredHTTPClient(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte(sampleListBucketsXML))
	}))
	defer server.Close()

	counter := &countingHTTPClient{inner: server.Client()}

	cli := &Client{Client: s3.New(s3.Options{
		BaseEndpoint: aws.String(server.URL),
		Region:       "auto",
		Credentials:  credentials.NewStaticCredentialsProvider("test-key", "test-secret", ""),
		HTTPClient:   counter,
	})}

	if _, err := cli.ListSoftDeletedBuckets(context.Background(), nil); err != nil {
		t.Fatal(err)
	}

	if counter.calls != 1 {
		t.Errorf("configured HTTP client saw %d requests, want 1", counter.calls)
	}
}
